<?php
declare(strict_types=1);
namespace DigiForge\Tests;
use PHPUnit\Framework\TestCase;
use DigiForge\POD\{PrintifyAcceptancePolicy,PrintifyAcceptanceBinding,PrintifyAcceptanceContract};
foreach(['PrintifyAcceptancePolicy','PrintifyAcceptanceBinding','PrintifyAcceptanceContract'] as $c){$p=__DIR__.'/../../includes/POD/'.$c.'.php';if(is_file($p))require_once $p;}
final class PrintifyAcceptancePreparationTest extends TestCase {
 public function testProposalNeverProvidesRuntimeAuthority():void {self::assertTrue(class_exists(PrintifyAcceptancePolicy::class),'Inactive policy contract required');$p=PrintifyAcceptancePolicy::proposal();self::assertFalse($p['enabled']);self::assertFalse($p['runtime_execution_authorized']);foreach(['GET','POST','PUT','PATCH','DELETE'] as $method){$r=PrintifyAcceptancePolicy::decision($method,true,true);self::assertFalse($r['runtime_execution_authorized']);self::assertSame('BLOCKED_AUTHORITY',$r['status']);}}
 public function testBindingUnknownsAndCanonicalIdentity():void {self::assertTrue(class_exists(PrintifyAcceptanceBinding::class),'Binding validator required');$p=PrintifyAcceptanceBinding::proposal();$r=PrintifyAcceptanceBinding::validate($p,[],time());self::assertContains('ACCOUNT_ASSOCIATION_UNKNOWN',$r['blockers']);self::assertContains('CREDENTIAL_REFERENCE_UNKNOWN',$r['blockers']);self::assertFalse($r['runtime_execution_authorized']);$p['provider_shop_id']='28925875';self::assertContains('PROVIDER_SHOP_MISMATCH',PrintifyAcceptanceBinding::validate($p,[],time())['blockers']);}
 /** @dataProvider invalidTransport */
 public function testTransportBoundsRejectInvalidValues(array $change):void {self::assertTrue(method_exists(PrintifyAcceptanceContract::class,'transport'),'Strict bounded transport admission required');$args=array_replace(['method'=>'GET','timeout'=>20,'redirection'=>0,'sslverify'=>true,'reject_unsafe_urls'=>true,'limit_response_size'=>1048577,'headers'=>['Authorization'=>'Bearer synthetic','User-Agent'=>'DigiForge','Accept'=>'application/json']],$change);$this->expectException(\InvalidArgumentException::class);PrintifyAcceptanceContract::transport('/v1/shops.json','https://api.printify.com/v1/shops.json',$args);}
 public static function invalidTransport():array{return [[['timeout'=>0]],[['timeout'=>-1]],[['timeout'=>21]],[['limit_response_size'=>0]],[['limit_response_size'=>-1]],[['limit_response_size'=>1048578]],[['sslverify'=>false]],[['redirection'=>1]],[['body'=>null]],[['headers'=>['Authorization'=>"Bearer x\r\nInjected: yes"]]],[['headers'=>['Authorization'=>'Bearer synthetic','User-Agent'=>'DigiForge','X-Injected'=>'yes']]]];}
 private function validBinding():array {$p=PrintifyAcceptanceBinding::proposal();$p=array_replace($p,['account_reference'=>'synthetic-account','credential_reference'=>['integration_id'=>3,'secret_name'=>'personal_access_token','metadata_sha256'=>str_repeat('a',64)],'catalog_scope'=>['business_id'=>1,'store_id'=>2,'product_program'=>'PERSONALIZED_POD'],'evidence_revision'=>2,'approval_sha256'=>str_repeat('b',64),'observed_at'=>1000,'expires_at'=>1300,'integration_enabled'=>true]);$e=['account_association_verified'=>true,'account_reference'=>'synthetic-account','credential_reference_present'=>true,'credential_metadata_sha256'=>str_repeat('a',64),'credential_account_association_verified'=>true,'registry_scope_verified'=>true,'duplicate_mapping'=>false,'cross_shop_conflict'=>false,'provider_scope_verified'=>true,'integration_enabled'=>true,'evidence_revision'=>2,'approval_sha256'=>str_repeat('b',64),'independent_approval_valid'=>true,'authority_revoked'=>false];return [$p,$e];}
 public function testValidatedOfflineEvidenceStillCannotGrantAccess():void {[$p,$e]=$this->validBinding();$r=PrintifyAcceptanceBinding::validate($p,$e,1100);self::assertSame('OFFLINE_PROPOSAL_VALIDATED',$r['status']);self::assertFalse($r['runtime_execution_authorized']);self::assertFalse($r['binding_write_authorized']);}
 /** @dataProvider bindingFaults */
 public function testEveryBindingGateRejectsFault(string $field,mixed $value,string $code,bool $proposal=false):void {[$p,$e]=$this->validBinding();if($proposal)$p[$field]=$value;else $e[$field]=$value;self::assertContains($code,PrintifyAcceptanceBinding::validate($p,$e,1100)['blockers']);}
 public static function bindingFaults():array {return [['integration_id',4,'IDENTITY_INTEGRATION_ID',true],['internal_shop_id',3,'IDENTITY_INTERNAL_SHOP_ID',true],['shop_key','standard_pod','IDENTITY_SHOP_KEY',true],['provider_shop_id','28925875','PROVIDER_SHOP_MISMATCH',true],['environment','test','WRONG_ENVIRONMENT',true],['excluded_provider_shop_id','28930593','PROPOSAL_SCHEMA_OR_EXCLUSION_INVALID',true],['schema','wrong','PROPOSAL_SCHEMA_OR_EXCLUSION_INVALID',true],['account_reference','different','ACCOUNT_ASSOCIATION_UNKNOWN'],['credential_metadata_sha256',str_repeat('c',64),'CREDENTIAL_REFERENCE_UNKNOWN'],['credential_account_association_verified',false,'CREDENTIAL_ACCOUNT_ASSOCIATION_UNKNOWN'],['duplicate_mapping',true,'DUPLICATE_MAPPING_OR_UNKNOWN'],['cross_shop_conflict',true,'CROSS_SHOP_CONFLICT_OR_UNKNOWN'],['provider_scope_verified',false,'PROVIDER_SCOPE_UNVERIFIED'],['integration_enabled',false,'INTEGRATION_DISABLED_OR_UNKNOWN'],['evidence_revision',1,'UNREVIEWED_BINDING'],['authority_revoked',true,'REVOKED_OR_UNKNOWN_AUTHORITY'],['expires_at',1050,'STALE_OR_EXPIRED_EVIDENCE',true],['observed_at',700,'STALE_OR_EXPIRED_EVIDENCE',true],['catalog_scope',null,'CATALOG_SCOPE_MISSING',true]];}
 public function testAuthorityExpiryRevocationSignatureAndScopeAreValidationOnly():void {$a=['owner_actor_id'=>1,'owner_verified'=>true,'shop_key'=>'personalized_pod','integration_id'=>3,'provider_shop_id'=>'28930593','account_reference'=>'synthetic-account','account_association_verified'=>true,'credential_metadata_sha256'=>str_repeat('a',64),'independent_review_valid'=>true,'delegation_required'=>true,'signed_delegation_valid'=>true,'revoked'=>false,'issued_at'=>1000,'expires_at'=>1300];[$binding]=$this->validBinding();self::assertSame([],PrintifyAcceptancePolicy::authorityBlockers($a,1100,$binding));foreach([['owner_actor_id',2,'OWNER_AUTHORITY_INVALID'],['shop_key','standard_pod','AUTHORITY_SCOPE_MISMATCH'],['account_association_verified',false,'AUTHORITY_ACCOUNT_UNKNOWN'],['account_reference','other','AUTHORITY_ACCOUNT_UNKNOWN'],['credential_metadata_sha256',str_repeat('c',64),'AUTHORITY_CREDENTIAL_MISMATCH'],['signed_delegation_valid',false,'SIGNED_DELEGATION_INVALID'],['revoked',true,'AUTHORITY_REVOKED_OR_UNKNOWN'],['expires_at',1050,'AUTHORITY_EXPIRED_OR_INVALID'],['independent_review_valid',false,'INDEPENDENT_REVIEW_MISSING']] as [$k,$v,$reason]){self::assertContains($reason,PrintifyAcceptancePolicy::authorityBlockers(array_replace($a,[$k=>$v]),1100,$binding));}self::assertFalse(PrintifyAcceptancePolicy::decision('GET',false,false)['runtime_execution_authorized']);}
 public function testPositiveTransportIsFixedAndSecretSafe():void {$a=['method'=>'GET','timeout'=>20,'redirection'=>0,'sslverify'=>true,'reject_unsafe_urls'=>true,'limit_response_size'=>1048577,'headers'=>['Authorization'=>'Bearer synthetic','User-Agent'=>'DigiForge','Accept'=>'application/json']];PrintifyAcceptanceContract::transport('/v1/shops.json','https://api.printify.com/v1/shops.json',$a);self::assertTrue(true);$this->expectException(\InvalidArgumentException::class);PrintifyAcceptanceContract::transport('/v1/shops.json','https://evil.test/v1/shops.json',$a);}

 public function testPublishedProposalIsCanonicalAndMissingKeysFail():void {$p=json_decode(file_get_contents(__DIR__.'/../../docs/engineering/printify-api/SHOP2-ACCEPTANCE-BINDING-PROPOSAL.json'),true);self::assertSame(PrintifyAcceptanceBinding::proposal(),$p);unset($p['schema']);self::assertContains('INVALID_PROPOSAL_FIELDS',PrintifyAcceptanceBinding::validate($p,[],1100)['blockers']);}

}
